DECLARE
  v_client_id integer;
  v_pool_id integer;
  v_fileset_id integer;
  v_job_id integer;
BEGIN
  -- Resolve client (auto-create if missing)
  SELECT clientid INTO v_client_id FROM client WHERE name = p_client;
  IF v_client_id IS NULL THEN
    INSERT INTO client (name, uname, autoprune, fileretention, jobretention)
    VALUES (p_client, '', 1, 2592000, 15552000)
    RETURNING clientid INTO v_client_id;
  END IF;

  -- Resolve pool
  SELECT poolid INTO v_pool_id FROM pool WHERE name = p_pool;
  IF v_pool_id IS NULL THEN v_pool_id := 0; END IF;

  -- Resolve fileset
  SELECT filesetid INTO v_fileset_id FROM fileset WHERE fileset = p_fileset;
  IF v_fileset_id IS NULL THEN v_fileset_id := 0; END IF;

  -- Insert job
  INSERT INTO job (job, name, type, level, clientid, jobstatus,
    schedtime, starttime, realendtime, jobtdate,
    volsessionid, volsessiontime, jobfiles, jobbytes, joberrors,
    poolid, filesetid, priorjobid, hasbase, hascache, reviewed, comment)
  VALUES (p_job, p_name, p_type, p_level, v_client_id, 'C',
    to_timestamp(p_sched_time::float8), to_timestamp(p_sched_time::float8),
    to_timestamp(p_sched_time::float8), p_sched_time,
    0, 0, 0, 0, 0, v_pool_id, v_fileset_id, 0, 0, 0, 0, '')
  RETURNING jobid INTO v_job_id;

  RETURN v_job_id;
END;
